use Qwiratry::Query::Slang;

my $repo = ⮳ <https://api.github.com/repos/Raku/doc> ↱ <JSON>;

my %summary =
  full_name   => $repo ⥷ <full_name>,
  stars       => $repo ⥷ <stargazers_count>,
  open_issues => $repo ⥷ <open_issues_count>,
  language    => $repo ⥷ <language>,
;

say %summary ↴ <JSON> :pretty;

use Ecosystem;
use Qwiratry::Query::Slang;

my $eco = Ecosystem.new(:ecosystem<fez>);

# Latest identities for one author — swap the auth to taste
my @identities = $eco.find-identities(:auth<zef:wayland>, :latest).head(5);

sub github-contributors-url(Str $source-url --> Str) {
    # Accept https://github.com/owner/repo(.git)? and friends
    return '' unless $source-url ~~ m{ 'github.com/' <owner=[\w.-]+> '/' <repo=[\w.-]+> };
    my $repo = (~$<repo>).subst(/\.git$/, '');
    return "https://api.github.com/repos/$<owner>/$repo/contributors";
}

my @report;
for @identities -> $identity {
    my %meta = $eco.identities{$identity};
    my $name = %meta<name> // $identity;

    # Attribute operator works on ordinary hashes too
    # (Ecosystem already gave us a Map; we still navigate it as a tree)
    my $source = (%meta ⥷ <source-url>) // '';

    my $contrib-url = github-contributors-url($source);
    my $count = Nil;
    if $contrib-url {
        my $contributors = ⮳ $contrib-url ↱ <JSON>;
        $count = $contributors.elems;   # JSON array → number of contributor objects
    }

    @report.push: %(
        name          => $name,
        identity      => ~$identity,
        source-url    => $source,
        contributors  => $count,
    );
}

say @report ↴ <JSON> :pretty;
